def fake_embed(text):
    # a real model learns this from data; here we simulate a tiny 3D embedding
    text = text.lower()
    animal_score = sum(word in text for word in ["dog", "puppy", "cat", "kitten"])
    action_score = sum(word in text for word in ["running", "sprinting", "jumping"])
    weather_score = sum(word in text for word in ["rain", "sunny", "cloudy"])
    return (animal_score, action_score, weather_score)

def euclidean_distance(v1, v2):
    return sum((a - b) ** 2 for a, b in zip(v1, v2)) ** 0.5

sentences = {
    "a": "A dog is running in the park.",
    "b": "A puppy is sprinting across the yard.",
    "c": "It is raining heavily today.",
}

embeddings = {key: fake_embed(text) for key, text in sentences.items()}
print("Embeddings:")
for key, vec in embeddings.items():
    print(f"  {key}: {vec}")

print("\nDistances:")
print(f"  a to b (similar meaning): {euclidean_distance(embeddings['a'], embeddings['b']):.2f}")
print(f"  a to c (different meaning): {euclidean_distance(embeddings['a'], embeddings['c']):.2f}")
